   214→// ============================================================================
   215→// INSTRUCTION EXECUTION
   216→// ============================================================================
   217→
   218→// Execute a single instruction
   219→fn vm_execute_instruction(vm: struct, opcode: i32) -> bool {
   220→  if opcode == opcode_push() {
   221→    // PUSH: push next value (from instruction stream)
   222→    // For now, push 0 as placeholder
   223→    return vm_push(vm, 0)
   224→  }
   225→  else if opcode == opcode_pop() {
   226→    // POP: discard top of stack
   227→    let _ = vm_pop(vm);
   228→    return vm.error == ""
   229→  }
   230→  else if opcode == opcode_add() {
   231→    return vm_add(vm)
   232→  }
   233→  else if opcode == opcode_sub() {
   234→    return vm_sub(vm)
   235→  }
   236→  else if opcode == opcode_mul() {
   237→    return vm_mul(vm)
   238→  }
   239→  else if opcode == opcode_div() {
   240→    return vm_div(vm)
   241→  }
   242→  else if opcode == opcode_load() {
   243→    // LOAD: pop address, load from memory
   244→    let address = vm_pop(vm);
   245→    if vm.error != "" {
   246→      return false
   247→    }
   248→    let value = vm_load(vm, address);
   249→    if vm.error != "" {
   250→      return false
   251→    }
   252→    return vm_push(vm, value)
   253→  }
   254→  else if opcode == opcode_store() {
   255→    // STORE: pop value and address, store to memory
   256→    let value = vm_pop(vm);
   257→    let address = vm_pop(vm);
   258→    if vm.error != "" {
   259→      return false
   260→    }
   261→    return vm_store(vm, address, value)
   262→  }
   263→  else if opcode == opcode_halt() {
   264→    vm.halted = true;
   265→    return true
   266→  }
   267→  else {
   268→    vm.error = "Unknown opcode";
   269→    return false
   270→  }
   271→}
