   273→// ============================================================================
   274→// VM EXECUTION
   275→// ============================================================================
   276→
   277→// Execute a program (array of opcodes)
   278→fn vm_run(vm: struct, program: array) -> struct {
   279→  while !vm.halted && vm.instruction_pointer < length(program) {
   280→    let opcode = program[vm.instruction_pointer];
   281→
   282→    if !vm_execute_instruction(vm, opcode) {
   283→      vm.halted = true;
   284→      break
   285→    }
   286→
   287→    vm.instruction_pointer = vm.instruction_pointer + 1
   288→  }
   289→
   290→  return vm
   291→}
   292→
   293→// Get execution result from VM state
   294→fn vm_get_result(vm: struct) -> i32 {
   295→  if vm.stack_pointer > 0 {
   296→    return vm.stack[vm.stack_pointer - 1]
   297→  }
   298→  return 0
   299→}
